const fs = require("fs");
function readNum(f) {
  const raw = fs.readFileSync(f, "utf8").trim();
  const n = Number(raw);
  if (raw === "" || !Number.isFinite(n)) throw new Error(`non-numeric value in ${f}: "${raw}"`);
  return n;
}
const seed = readNum("seed.txt");
const stage1 = readNum("stage1.txt");
const stage2 = readNum("stage2.txt");
const stage3 = readNum("stage3.txt");

const checks = [
  ["stage1 = seed + 2", stage1, seed + 2],
  ["stage2 = stage1^2", stage2, stage1 * stage1],
  ["stage3 = stage2 - 4", stage3, stage2 - 4],
];
let ok = true;
for (const [label, actual, expected] of checks) {
  const pass = actual === expected;
  if (!pass) ok = false;
  console.log(`${pass ? "PASS" : "FAIL"}  ${label}: saved=${actual} expected=${expected}`);
}
if (!ok) { console.error("verification failed; answer.json not written"); process.exit(1); }

const answer = { stage1, stage2, stage3 };
fs.writeFileSync("answer.json", JSON.stringify(answer, null, 2));
const back = JSON.parse(fs.readFileSync("answer.json", "utf8"));
console.log("wrote answer.json:", JSON.stringify(back));
for (const k of ["stage1", "stage2", "stage3"]) {
  if (typeof back[k] !== "number" || back[k] !== answer[k]) {
    console.error(`answer.json key ${k} mismatch`); process.exit(1);
  }
}
console.log("answer.json keys numeric and equal to saved stage values: true");
'
